```python
import time
from functools import wraps

def retry(max_attempts: int, delay: float, exceptions: tuple):
    """
    Decorador para reintentar una función en caso de excepciones específicas.

    :param max_attempts: Número máximo de intentos totales.
    :param delay: Segundos de espera entre reintentos.
    :param exceptions: Tupla de tipos de excepción que deben disparar el reintento.
    """
    def decorator(func):
        @wraps(func)  # Preserva los metadatos de la función original (nombre, docstring, etc.)
        def wrapper(*args, **kwargs):
            last_exception = None

            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
                    # Si no es el último intento, esperamos antes de reintentar
                    if attempt < max_attempts:
                        print(f"⚠️ Intento {attempt}/{max_attempts} falló ({type(e).__name__}). "
                              f"Reintentando en {delay}s...")
                        time.sleep(delay)
                    else:
                        print(f"❌ Se agotaron los {max_attempts} intentos.")
                except Exception as e:
                    # Si la excepción no está en la tupla permitida, la lanzamos de inmediato
                    raise e

            # Si el bucle termina sin éxito, relanzamos la última excepción capturada
            if last_exception:
                raise last_exception

        return wrapper
    return decorator

# --- Pruebas de uso ---

# 1. Caso de éxito tras un fallo
